import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AP everyday-crime stories.
extension FollowUpCases {
    static let batchAP: [CaseTemplate] = [tipSkimTwo, texterNoLicense, catInHotCar, fakeRoofer, foundWalletKept, radioTowerClimb, bananaTwo, inflatablesYard, graveyardScene, witnessThreatLetter, dwlrAfterCrash, stolenSafeResale, insuranceFireClaim, stalkingCourtOrderAbduction, pillMillAgain, workplaceThreat, jailAssault, wrenchAssaultThreat]

    static let tipSkimTwo = SmallCases.make(
        key: "story.followup.tipSkimTwo",
        category: .property,
        headlines: ["Server at New Restaurant Accused of Skimming Tip Jar Again", "Second Tip Jar Complaint Names Defendant From Earlier Case"],
        law: "misdLarceny",
        spec: "Stole $260 in shared tips belonging to {V}, a restaurant's staff, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took a job at a diner across town. The owner, {V}, noticed the tip jar coming up short and watched the register camera. It showed {DL} folding bills into an apron pocket. {DL} says the bills were change {D.he} was owed.",
        state: [E(.video, 3, "Register Camera", "{D} folds bills into an apron pocket twice."), E(.document, 2, "Tip Log", "The jar was $260 short at close.")],
        defense: [E(.statement, 1, "Change", "{DL} says the cash was change from a table.")],
        role: "Diner owner",
        exam: [.direct("How long have you run the diner?", "\"I have owned it for eleven years. It is a small place with six servers and a couple of busers, and the tip jar by the register is how they make a lot of their pay.\""),
               .direct("What made you suspect something was wrong with the jar?", "\"The jar kept coming up short at close, a little at a time. It started about two weeks after {DL} was hired, so I put a camera on the register.\""),
               .direct("What did the register camera show?", "\"It shows {DL} reaching toward the jar, folding bills, and putting them into an apron pocket. That happened twice during the same shift, about an hour apart.\""),
               .direct("How short was the jar that night?", "\"$260 by my count at close. I tallied it against the tip log the servers keep, and the numbers did not match.\""),
               .direct("What did you do when you saw the footage?", "\"I watched it three times before I said anything to anyone. Then I called the sheriff's office and handed them the clip and the tip log.\""),
               .direct("Did you talk to {DL} about it?", "\"Yes, the next morning. {D.He} said the bills were change from a table that {D.he} was owed, and {D.he} did not argue much beyond that.\""),
               .direct("How have things changed at the diner?", "\"Now I count the jar in front of everyone at close. I hated being right about this, because I liked {D.him} as a worker and had given {D.him} a chance.\""),
               .cross("{DL} says the cash was change from a table, doesn't {D.he}?", "\"{D.He} said so to my face the next morning. But the jar is not a till, and change from a table goes in the register or back to the customer.\""),
               .cross("Isn't it possible a customer told {DL} to keep some change?", "\"Customers do that, but tips go to the jar, and that is the rule every server here knows. {DL} knew the rule.\""),
               .cross("Can you tell from the video whose money it was?", "\"No, the video shows bills going into the pocket. It does not show the table or who paid the money.\""),
               .cross("Other staff reach into that jar too, don't they?", "\"Busers put money in and make change from it sometimes, yes. But I watched the clip, and nobody else was near it at those times.\""),
               .cross("You counted the shortage by hand, correct?", "\"Yes, I counted it myself against the log. I could have been off by a few dollars, but not by $260.\"")],
        theory: ("{D} skimmed bills from the diner's tip jar, and did it again after an earlier case.", "{D} kept what {D.he} believed was change from a table and put it in an apron pocket."),
        allocution: "\"I folded those bills into my apron because I believed they were change I was owed from a table, and I should have put them in the jar or asked the owner. I know how it looked on the camera. I've worked for tips a long time, and I'd never want to take from my coworkers. I'm sorry for the trouble I caused {V}.\"",
        truths: ("{DL}'s old restaurant had warned the owner.", "The diner's tip jar was shared with a dozen busers who all reached into it."),
        defendant: [.direct("Did you take money from the tip jar?", "\"I took bills I believed were change that I was owed from a table. I did not think of it as taking from the jar.\""),
               .direct("What happened at that table?", "\"A customer paid with a large bill and told me to keep a few dollars. I made change from what was in the jar and kept my part.\""),
               .direct("Why did you put the bills in your apron pocket?", "\"It was a busy shift, and I did not want to lose track of them. I meant to sort it out with the other servers at close.\""),
               .direct("Did you tell anyone what you had done?", "\"No, and that was a mistake. I should have told the owner or put the money in the jar.\""),
               .direct("How did you feel when the owner confronted you?", "\"Embarrassed and afraid. I knew how the camera looked, and I could tell the owner did not believe me.\""),
               .direct("What do you want {V} to know?", "\"I would never want to take from my coworkers. I am sorry for the trouble I caused the diner.\""),
               .cross("You folded bills into your apron twice in one shift, didn't you?", "\"Yes, I did, and I know how that looks on the camera. I have worked for tips a long time, and I should have done it differently.\""),
               .cross("You had a case in this court before, in {PRIORDATE}, hadn't you?", "\"Yes, I know, and I hoped this job would be a fresh start. I should have been more careful with the jar.\""),
               .cross("The jar was $260 short that night, wasn't it?", "\"That is what the owner says. I did not take that much, and I cannot explain the rest.\""),
               .cross("You did not ask the owner whether you could keep the change?", "\"No, I did not ask, because I believed it was mine to keep. I know now that I should have asked.\""),
               .cross("The jar is shared among the servers, isn't it?", "\"Yes, it is shared, and that is why I should have left it alone. Whatever I took belonged to the group.\"")],
        openings: ("A diner owner put a camera on the register after the tip jar kept coming up short. It shows {D}, a new hire, folding bills into an apron pocket twice in one shift, and the jar was $260 short at close. This is not {DL}'s first time in this court: in {PRIORDATE} there was a case over {PRIOR}.", "The defense will present a server who made change from a table in a rush, in full view of a register camera. Folding bills into an apron is not hiding anything, and a mix-up about change is not a larceny."),
        closings: ("The camera shows bills going into an apron pocket twice in one shift, and the jar was $260 short. {D} had been in this court before, and the jar is not a till.", "A busy shift, a customer who paid with a large bill, and a server who put change in a pocket in plain view of a camera. The State has not shown that {D} meant to steal anyone's tips."),
        timeline: [(-14, "{D} starts work at the diner."), (0, "The register camera records {D} pocketing bills from the tip jar twice in one shift."), (0, "The jar is counted $260 short at close."), (1, "{V} reviews the footage and reports it to the sheriff's office.")],
        identified: "The owner's register camera.",
        impact: "Once was enough. I run a small diner, and the tips are how my servers pay their bills. I put up a camera because the jar kept coming up short, and I watched a new hire fold bills into an apron pocket. I hated being right. Now I count the jar in front of everyone.",
        genders: ["D": .female])

    static let texterNoLicense = SmallCases.make(
        key: "story.followup.texterNoLicense",
        category: .traffic,
        headlines: ["Driver Whose License Was Revoked After Crash Stopped Behind the Wheel", "Revoked Driver Caught on Highway Weeks After Texting Crash"],
        law: "dwlr",
        spec: "Operated a motor vehicle on a highway while {D.his} license was revoked, on {DATE}.",
        ages: 18...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}'s license was revoked. A trooper stopped {DL} on the same highway for a tail light. {DL} said {D.he} thought the revocation was over and had no other way to get to work.",
        state: [E(.document, 3, "DMV Record", "The revocation was active; notice mailed to {D}'s address."), E(.statement, 2, "Trooper", "{D} said {D.he} thought the revocation had ended.")],
        defense: [E(.statement, 1, "No Ride", "{DL} says {D.he} had no other way to get to work.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What is your assignment with the Highway Patrol?", "\"I am a state trooper assigned to this stretch of highway. I run traffic stops, crash scenes, and license checks, and I have been on patrol for twelve years.\""),
               .direct("Why did you stop {DL}?", "\"A tail light was out on the car. I pulled in behind it, and when I ran the plate, the registered owner came back with a revoked license.\""),
               .direct("What did the DMV record show?", "\"It showed an active revocation from the crash case. The record also showed a notice was mailed to {D}'s address on file.\""),
               .direct("Was the revocation still in effect that day?", "\"Yes, it had not expired and no restoration had been issued. The record showed no limited privilege either.\""),
               .direct("What did {DL} say to you?", "\"{D.He} said {D.he} thought the revocation was over and that {D.he} had no other way to get to work. {D.He} was polite and did not argue.\""),
               .direct("Why does a revocation matter on that road?", "\"That is the same highway where {D} was involved in a texting crash that hurt people. The point of the revocation is to keep that driver off the road.\""),
               .direct("What did you do?", "\"I issued a citation for driving while license revoked. I also told {D.him} not to drive until things were straightened out.\""),
               .cross("Did {DL} seem to know about the revocation?", "\"{D.He} said {D.he} thought it was over. I cannot tell you what was in {D.his} mind.\""),
               .cross("Was the notice sent to the correct address?", "\"It was sent to the address on file with the DMV. I do not know whether {D.he} still lived there.\""),
               .cross("Did {DL} say anything about needing to get to work?", "\"Yes, {D.he} said {D.he} had no ride to work. I understand that, but it does not give a person permission to drive.\""),
               .cross("Was the driving itself unsafe?", "\"No, {D.he} was driving normally. The only violation I saw was the tail light.\""),
               .cross("You cannot say whether {DL} read the notice, can you?", "\"No, I cannot. I can tell you it was mailed and that the revocation was still active.\"")],
        theory: ("{D} drove on a highway while {D.his} license was revoked after a texting crash.", "{D} honestly believed the revocation was over and had no other way to get to work."),
        allocution: "\"I truly thought my revocation was over, and I had no other way to get to work. The notice was mailed to an old address, and I forgot to check my record. I know a crash got me here in the first place. I'm sorry to the trooper, and I'll get my license sorted out before I drive again.\"",
        truths: ("{DL} had signed the revocation notice at the last hearing.", "The DMV mailed it to an old address."),
        defendant: [.direct("Did you know your license was revoked?", "\"I truly thought the revocation was over. I had counted the months, and I believed it had ended.\""),
               .direct("Why were you driving that day?", "\"I had no other way to get to work. My shift started within the hour, and nobody could give me a ride.\""),
               .direct("Did you get a notice about the revocation?", "\"One was mailed to an old address, and I never saw it. I forgot to check my record after I moved.\""),
               .direct("Did you sign anything at the last hearing?", "\"I was handed some papers, and I may have signed them. I did not read them closely because I was nervous.\""),
               .direct("What do you remember about the stop?", "\"The trooper was polite, and I told the truth right away. I said I thought it was over.\""),
               .direct("What would you do differently?", "\"I would check my record first, and I would find a ride. I will get my license sorted out before I drive again.\""),
               .cross("You had a revoked license because of a texting crash, didn't you?", "\"Yes, that is why I was revoked, and I know people were hurt. I have thought about that every day since.\""),
               .cross("You signed the revocation notice at the last hearing, didn't you?", "\"I may have signed some papers there. I do not remember that specific notice.\""),
               .cross("You were in this court before, in {PRIORDATE}, for {PRIOR}, weren't you?", "\"Yes, I was, and I should have checked the record before driving. I did not, and I have to answer for that.\""),
               .cross("You had options besides driving, such as a bus or a ride, correct?", "\"The bus does not run out to my work at that hour. I could have called someone, and I should have.\""),
               .cross("You never contacted the DMV to ask whether your license was restored, did you?", "\"No, I did not call. I assumed enough time had passed, and I was wrong.\"")],
        openings: ("After a texting crash that hurt people, {D}'s license was revoked, and the DMV mailed notice to the address on file. Months later a trooper stopped {DL} on the same highway for a tail light, and the record showed the revocation was still active. {DL}'s earlier case in this court, in {PRIORDATE}, was over {PRIOR}.", "The defense will present a worker who believed the revocation had ended and whose notice went to an old address. Driving to a job without knowing the license was still revoked is a mistake, not a defiance of the court."),
        closings: ("The record shows an active revocation, a notice mailed to the address on file, and {D} behind the wheel on the same highway as the crash. {D} had been here before and knew what the revocation meant.", "The notice went to an old address, and {D} told the trooper the truth at once. The State has not shown that {D} knew the license was still revoked."),
        timeline: [(-300, "{D}'s license is revoked after a texting crash, and notice is mailed to the address on file."), (0, "A trooper stops {D} on the same highway for a tail light."), (0, "The DMV record shows the revocation is still active."), (0, "The trooper cites {D} for driving while license revoked.")],
        identified: "A trooper's stop.",
        impact: "Three years of this. I've pulled that driver over, or one just like it, again and again. After a texting crash that hurt people, a revoked license should mean something. I'm tired of arriving at wrecks I could have prevented. I just want the roads to be safe for the families on them.")

    static let catInHotCar = SmallCases.make(
        key: "story.followup.catInHotCar",
        category: .publicOrder,
        headlines: ["Cat Found Panting in Locked Car Outside Grocery Store, Owner Charged Again", "Second Animal-in-Car Complaint for Defendant From Earlier Case"],
        law: "animalCruelty",
        spec: "Maliciously or unreasonably deprived an animal of necessary sustenance and shelter, on {DATE}.",
        ages: 20...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a shopper called police about a cat panting in a locked car at a grocery lot on a 91-degree day. A deputy opened the car and cooled the cat with water. {DL} said {D.he} was only inside for a few minutes.",
        state: [E(.statement, 3, "Deputy", "The interior was 118 degrees; the cat was panting."), E(.video, 2, "Store Camera", "{D} entered at 1:05 and left at 1:51.")],
        defense: [E(.statement, 1, "A Few Minutes", "{DL} says {D.he} was in the store only a few minutes.")],
        role: "Sheriff's deputy",
        exam: [.direct("What was the weather that day?", "\"It was a 91-degree day with bright sun and no clouds. Asphalt in a grocery lot gets even hotter than the air, and cars heat up fast in that.\""),
               .direct("How did you come to the grocery lot?", "\"A shopper called police about a cat panting in a locked car. I was nearby and arrived within a few minutes.\""),
               .direct("What did you find?", "\"A cat in a locked car, panting hard and drooling. The windows were cracked about an inch, which does nothing in that heat.\""),
               .direct("What was the temperature inside the car?", "\"My thermometer read 118 degrees. That is hot enough to cause heatstroke in a cat in minutes.\""),
               .direct("What did you do?", "\"I opened the car, brought the cat into the shade, and cooled it with water. It was limp but breathing, and I stayed with it until it recovered.\""),
               .direct("What did the store camera show?", "\"It shows {DL} entering the store at 1:05 and leaving at 1:51. That is forty-six minutes.\""),
               .direct("How did the cat recover?", "\"It seemed to recover, though it was weak. I had an animal control officer check it over before it went home.\""),
               .cross("The windows were cracked, weren't they?", "\"An inch, yes. That is not enough to keep a car cool in that sun.\""),
               .cross("Was {DL} in the store the whole time?", "\"The camera shows {D.him} inside from 1:05 to 1:51. I cannot say where {D.he} went inside.\""),
               .cross("Did {DL} come out right away when you called?", "\"{D.He} came out when I had the cat in the shade. {D.He} said {D.he} had only been a few minutes.\""),
               .cross("Was there any shade near the car?", "\"The car was in the open, in the sun. There was a tree at the far edge of the lot, but not near the car.\""),
               .cross("You did not see {DL} leave the cat, did you?", "\"No, I arrived after the call. I only know what the camera and the shopper showed me.\"")],
        theory: ("{D} left a cat in a hot car for forty-six minutes while shopping.", "{D} meant to be gone only a few minutes and was held up by a slow checkout line."),
        allocution: "\"I only left the cat in the car for a few minutes, and the checkout line was slow. I had never meant to be gone that long, and I lost track of time. I love that animal, and I'm sorry that it was in danger on such a hot day. I'll never leave a pet in a car again.\"",
        truths: ("The store camera showed {DL} browsing aisles for twenty minutes before the line.", "The receipt shows a 20-minute checkout line, and a friend watched the car for ten of the minutes."),
        defendant: [.direct("Did you leave the cat in the car?", "\"Yes, I did, for what I meant to be only a few minutes. I never intended to leave it there for the whole time that I was inside.\""),
               .direct("Why did you go into the store?", "\"I needed a few items and I had an appointment after. I thought it would be quick.\""),
               .direct("What happened in the store?", "\"The checkout line was very slow. I lost track of time, and I did not realize how long I had been gone.\""),
               .direct("How do you feel about your cat?", "\"I love that animal, and I would never want it to suffer. I am sorry that it was in danger.\""),
               .direct("Did you think about the heat?", "\"I thought the cracked windows would be enough. I was wrong, and I know that now.\""),
               .direct("What will you do differently?", "\"I will never leave a pet in a car again. I will bring it with me or leave it at home.\""),
               .cross("The camera shows you in the store for 46 minutes, doesn't it?", "\"Yes, it does, and I did not think it was that long. The line was slow, but I should have gone back sooner.\""),
               .cross("You browsed the aisles for about twenty minutes before the line, didn't you?", "\"I walked around looking for a few things. I did not realize how much time that took.\""),
               .cross("It was 91 degrees outside, wasn't it?", "\"Yes, it was hot, and I should have known better. I did not think the cat would be at risk that quickly.\""),
               .cross("You were in this court before, in {PRIORDATE}, for {PRIOR}, weren't you?", "\"Yes, I was, and I know how that looks. I should have been more careful.\""),
               .cross("Nobody watched the car the whole time you were inside, did they?", "\"A friend watched it for part of the time, but not all of it. I should have stayed myself or taken the cat in with me.\"")],
        openings: ("On a 91-degree afternoon, a shopper called police about a cat panting in a locked car in a grocery lot. A deputy measured 118 degrees inside, and the store camera shows {D} inside for forty-six minutes. {DL} had already appeared here in {PRIORDATE} on {PRIOR}.", "The defense will present a pet owner who meant to be gone only a few minutes and was held up in a slow checkout line. The windows were cracked, a friend helped watch the car, and the cat recovered fully."),
        closings: ("118 degrees inside the car, a panting cat, and forty-six minutes on the camera. {D} had been here before and knew better than to leave a pet in a car.", "A slow line and a lost sense of time, with the windows cracked and a friend watching part of it. The State has not shown that {D} meant to be cruel."),
        timeline: [(0, "1:05 p.m.: {D} enters the grocery store, leaving the cat in the car."), (0, "1:30 p.m.: a shopper calls police about a panting cat in a locked car."), (0, "1:40 p.m.: a deputy opens the car, measures 118 degrees inside, and cools the cat."), (0, "1:51 p.m.: {D} leaves the store.")],
        identified: "A store camera.",
        impact: "The cat nearly died. When I opened that car, it was panting and limp, and the thermometer said ninety-one outside. I carried it to the shade and poured water on it for twenty minutes. I think about how much longer it could have gone. Some owners don't understand how fast a car heats up.")

    static let fakeRoofer = SmallCases.make(
        key: "story.followup.fakeRoofer",
        category: .whiteCollar,
        headlines: ["Contractor Takes $3,000 Deposit, Never Starts Roof", "Defendant From Earlier Scam Case Faces New Deposit Complaint"],
        law: "falsePretenses",
        spec: "Obtained $3,000 from {V} by false pretenses, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} paid {D} a $3,000 deposit to replace a roof. {DL} never returned. The company address on the contract was a vacant lot. {DL} says the supplier delayed the shingles.",
        state: [E(.document, 3, "Contract", "A signed contract and a $3,000 deposit receipt."), E(.document, 2, "Address Check", "The company address is a vacant lot.")],
        defense: [E(.statement, 1, "Delay", "{DL} says shingles were backordered.")],
        role: "Homeowner",
        exam: [.direct("What did you hire {DL} to do?", "\"I hired {DL} to replace the roof on our house. It had been leaking for two winters, and we had saved up for the job.\""),
               .direct("What did you pay?", "\"A $3,000 deposit, paid on the day we signed the contract. I have the receipt and the contract in the file.\""),
               .direct("Did any work start?", "\"No. No one ever came to the house, no materials were delivered, and no crew showed up.\""),
               .direct("What happened when you tried to reach {DL}?", "\"I called and texted many times. A few days after the deposit, the phone was disconnected.\""),
               .direct("What did you find about the company's address?", "\"The address on the contract is a vacant lot. I drove out there myself and found nothing but weeds and a mailbox.\""),
               .direct("How has this affected your household?", "\"That was our savings. Every rain since has meant buckets in the hall, and we are still saving to hire someone honest.\""),
               .direct("What did you do next?", "\"I reported it to the sheriff's office with the contract, the receipt, and the address check. A detective took it from there.\""),
               .cross("{DL} says the shingles were delayed, doesn't {D.he}?", "\"That is what I have heard. No one ever told me about a delay at the time.\""),
               .cross("Did {DL} call you about a supplier?", "\"No. I never got a call, a text, or an email about shingles.\""),
               .cross("Was the address on the contract the only one you had?", "\"It was the only address I had. There was also a phone number, and that went dead.\""),
               .cross("Did {DL} seem sincere when you signed?", "\"{D.He} seemed friendly and professional. That is why I trusted {D.him} with the deposit.\""),
               .cross("You do not know whether a shingle order was placed, do you?", "\"No, I do not. I only know that no shingles ever came to my house.\"")],
        theory: ("{D} took a deposit for a roof and then vanished with the money.", "{D} meant to do the job and was held up by a supplier delay."),
        allocution: "\"I took that deposit fully meaning to replace the roof. The supplier delayed the shingles, and the work fell behind, and I did not handle it well. I'm sorry that I let {V} wait. I know the address on the contract was only a mailbox. I'll return every dollar of the three thousand.\"",
        truths: ("{DL}'s phone was disconnected the week after the deposit.", "A shingle order was placed and canceled."),
        defendant: [.direct("Did you take the deposit?", "\"Yes, I took it. I meant to replace the roof, and I told the homeowner so.\""),
               .direct("Did you intend to do the work?", "\"Yes, I did. I ordered shingles, and I planned to start the job as soon as they arrived.\""),
               .direct("What went wrong?", "\"The supplier delayed the shingles, and the work fell behind. I did not handle it well, and I stopped answering the phone.\""),
               .direct("Why was the address a vacant lot?", "\"It was a mailbox I rented, and I used it for the business. I should have told the homeowner.\""),
               .direct("Why did you disconnect your phone?", "\"I could not afford the bill. I was embarrassed that the job was late and I avoided the calls.\""),
               .direct("What will you do about the deposit?", "\"I will return every dollar of the three thousand. I am sorry that I let the homeowner wait.\""),
               .cross("You took $3,000 and never started the work, didn't you?", "\"That is true. I did not start, and I should have been honest about why.\""),
               .cross("You were in this court before, in {PRIORDATE}, weren't you?", "\"Yes, I was, and I know how that sounds to anyone hearing this. I have tried to do better.\""),
               .cross("The shingle order was placed and then canceled, wasn't it?", "\"I placed one, and the supplier canceled when I was late paying. I did not tell the homeowner.\""),
               .cross("You never called the homeowner about the delay, did you?", "\"No, I did not, and that was wrong. I avoided the call when I should have made it.\""),
               .cross("Your phone was disconnected the week after the deposit, wasn't it?", "\"Yes, it was, and I cannot say that looks good. I could not pay the bill.\"")],
        openings: ("{V} paid {D} a $3,000 deposit to replace a leaking roof, and no work ever started. The phone went dead within a week, and the company address on the contract is a vacant lot. {DL} stood before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a contractor who ordered shingles and meant to do the job, and a supplier that delayed delivery. A late job is a breach of contract, and the State must prove a lie at the start."),
        closings: ("The deposit was taken, the phone was disconnected, and the address sat empty. A person who intends to do a job answers the homeowner's calls.", "A shingle order that fell through and a contractor who handled it poorly. A late supplier is a delay, not a lie, and the State has not proved that {D} never meant to roof that house."),
        timeline: [(-30, "{V} signs a contract with {D} to replace the roof."), (-28, "{V} pays {D} a $3,000 deposit."), (-20, "{D}'s phone is disconnected."), (0, "{V} finds the company address is a vacant lot and reports it to the sheriff's office.")],
        identified: "The contract.",
        impact: "That was our savings. We paid three thousand dollars up front to replace a leaking roof, and then nobody came. The phone went dead, and the address turned out to be a vacant lot. Every rain since has meant buckets in the hall. We're still saving to hire someone honest.",
        genders: ["D": .male])

    static let foundWalletKept = SmallCases.make(
        key: "story.followup.foundWalletKept",
        category: .property,
        headlines: ["Man Who Found Wallet Used Its Cards, Police Say", "Second Found-Property Case for Defendant From Earlier Case"],
        law: "possStolen",
        spec: "Possessed a wallet and credit card belonging to {V}, knowing them to be stolen, on {DATE}.",
        ages: 18...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s lost wallet turned up with {D}. Two cards had been used at a gas station. {DL} says {D.he} found the wallet and meant to return it.",
        state: [E(.document, 3, "Card Statement", "Two charges at a gas station, $48."), E(.statement, 2, "Deputy", "The wallet was in {D}'s pocket.", .search)],
        defense: [E(.statement, 1, "Meant to Return", "{DL} says {D.he} meant to return it.")],
        role: "Wallet owner",
        exam: [.direct("What happened to your wallet?", "\"I lost it somewhere between the hardware store and my truck. I did not notice until I got home and went to pay for something.\""),
               .direct("What was in it?", "\"My license, two bank cards, some cash, and a note with my phone number that I keep in case I lose it.\""),
               .direct("How did you learn about the charges?", "\"I checked my bank account and saw two charges at a gas station. The total was $48.\""),
               .direct("What did you do?", "\"I canceled my cards and called the sheriff's office. A deputy later found the wallet in {DL}'s pocket.\""),
               .direct("Where was the wallet found?", "\"In {DL}'s pocket, according to the deputy. It still had my license in it and the note with my phone number.\""),
               .direct("Did {DL} ever contact you?", "\"Not that I know of. I did not get a call or a message from anyone about it.\""),
               .direct("What did it cost you?", "\"$48 on my cards, plus the time and trouble of replacing everything. A new license took most of a morning.\""),
               .cross("{DL} says {D.he} meant to return the wallet, doesn't {D.he}?", "\"That is what {D.he} says, and it may be true. But {D.he} used my cards before doing it.\""),
               .cross("Did {DL} offer the wallet back to you?", "\"Not yet. The deputy had to find it in {D.his} pocket.\""),
               .cross("Did {DL} leave a voicemail for you?", "\"I have a voicemail from an unknown number. I did not know whose it was until later.\""),
               .cross("Could you have lost the card yourself and someone else used it?", "\"The charges were at a gas station near where I lost it. They were made after the wallet was gone.\""),
               .cross("You never found the wallet yourself, did you?", "\"No, I did not. All I know is that a deputy recovered it from {DL}'s pocket after I reported it and canceled my cards.\"")],
        theory: ("{D} kept a lost wallet and used its bank cards at a gas station.", "{D} found a wallet and meant to return it."),
        allocution: "\"I found that wallet and I meant to return it, and I even left a voicemail for the number on the note. I used the card for gas, and I should not have. I'm sorry to {V}, and I should have turned it in at once. I'll pay back every dollar.\"",
        truths: ("{DL} used the card twice.", "{DL} left a voicemail for the number on the wallet's note the same day."),
        defendant: [.direct("Did you find the wallet?", "\"Yes, I found it on the ground in a parking lot. I picked it up and meant to return it.\""),
               .direct("What did you do with it?", "\"I called the number on the note and left a voicemail that same day. I wanted to get it back to the owner.\""),
               .direct("Why did you use the card?", "\"I needed gas, and I thought I would pay the owner back. I wish I had just waited until payday.\""),
               .direct("Did you use it more than once?", "\"Yes, twice. It was a total of $48, and I knew it was wrong as I did it.\""),
               .direct("Why was the wallet in your pocket when the deputy found you?", "\"I was on my way to drop it off. I had meant to return it that day.\""),
               .direct("What do you want {V} to know?", "\"I am sorry. I should have turned the wallet in at once, and I will pay back every dollar.\""),
               .cross("You used the card twice, didn't you?", "\"Yes, I did, and I should not have used it at all.\""),
               .cross("You were in this court before, in {PRIORDATE}, for {PRIOR}, weren't you?", "\"Yes, I was, and I should have known better than to touch someone else's card.\""),
               .cross("You did not turn the wallet in to the sheriff's office, did you?", "\"No, I did not. I meant to bring it to the owner.\""),
               .cross("You left a voicemail, but you did not leave your name, did you?", "\"I left a message with a phone number. I did not think a name mattered.\""),
               .cross("The wallet was in your pocket when the deputy found you?", "\"Yes, it was, with my own cards beside it. I had meant to drop it off that very afternoon on my way home.\"")],
        openings: ("{V} lost a wallet, and two cards were then used at a gas station for $48. A deputy found the wallet in {D}'s pocket, and {DL} was in this court before in {PRIORDATE} for {PRIOR}.", "The defense will present a finder who left a voicemail for the number on the wallet's note the same day. Finding a wallet and meaning to return it is not a theft."),
        closings: ("Two charges at a gas station, a wallet in {D}'s pocket, and no one returned. {D} had been in this court before.", "A voicemail, a note with a phone number, and a finder who meant to hand it back. The State has not shown that {D} meant to keep it."),
        timeline: [(0, "{V} loses the wallet near the hardware store."), (0, "Two gas station charges totaling $48 are made on {V}'s cards."), (1, "{D} leaves a voicemail for the number on the wallet's note."), (2, "A deputy finds the wallet in {D}'s pocket.")],
        identified: "A card statement.",
        impact: "Just return it. That's all I wanted when I lost that wallet. Instead, my card was used at a gas station twice, and I had to cancel everything and replace my license. It's a headache when someone could have just walked it to a counter. I hope the court sees how easy that would have been.",
        genders: ["D": .male])

    static let radioTowerClimb = SmallCases.make(
        key: "story.followup.radioTowerClimb",
        category: .publicOrder,
        headlines: ["Trespasser Climbs Radio Tower, Needs Rescue", "Second Climbing Incident for Defendant From Earlier Case"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a radio station, after being notified not to, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} climbed a radio tower behind {V}'s station and froze 80 feet up. Firefighters rescued {DL}. {DL} had been told in writing not to return to the property.",
        state: [E(.document, 3, "No-Trespass Notice", "A written notice from {V} to {D}."), E(.statement, 2, "Firefighter", "Rescued {D} at 80 feet.")],
        defense: [E(.statement, 1, "Fence Open", "{DL} says the gate was open.")],
        role: "Station manager",
        exam: [.direct("What is your position at the radio station?", "\"I am the station manager. I oversee the studio, the transmitters, and the grounds, including the tower behind the building that carries our signal.\""),
               .direct("Did {DL} have permission to be on the property?", "\"No. Some time earlier I gave {DL} a written no-trespass notice, and I keep the signed copy in my office file along with the date it was delivered.\""),
               .direct("How is the tower area secured?", "\"There is a fence around the base with warning signs about climbing, and the gate is chained at night. The insurance company requires it.\""),
               .direct("What happened that night?", "\"A passing driver saw a person high on the tower and called 911. {DL} had climbed about eighty feet and had frozen there, unable to go up or down.\""),
               .direct("Who rescued {DL}?", "\"The fire department. They set up ropes and a ladder truck, and it took them about an hour to bring {D.him} down safely.\""),
               .direct("How did this affect the station?", "\"We had to shut down part of our broadcast while crews worked near the transmitter. That cost us air time and advertising, and my engineer stayed until dawn.\""),
               .direct("Why does it matter to you that someone climbs that tower?", "\"A fall from that height would kill a person, and we would have to live with it. It also pulled firefighters away from other calls that night.\""),
               .cross("Was the gate locked when {DL} arrived?", "\"It was chained when I left that evening. I do not know whether the chain was properly locked at the moment {DL} got there.\""),
               .cross("Could the chain have been loose?", "\"It was supposed to be closed and locked. I did not check it again that night, so I cannot say.\""),
               .cross("Was the chain cut?", "\"The station's own report says the chain was cut when we looked the next morning. We do not know when that was done or by whom.\""),
               .cross("Did {DL} damage anything at the station?", "\"Not that I saw. The only loss was the cost of the rescue and the interruption of our broadcast.\""),
               .cross("You cannot say how {DL} got through the fence, can you?", "\"No, I cannot. I know only that {D.he} was on the tower, and that {D.he} had been told in writing to stay away.\"")],
        theory: ("{D} climbed a radio tower after being told in writing to stay off the property.", "{D} found an open gate and climbed on a dare."),
        allocution: "\"I climbed that tower on a dare, and I froze eighty feet up. The gate was open, and I thought it would be a quick climb. I know I was told in writing to stay away, and I shouldn't have gone. I'm sorry to the firefighters who had to rescue me, and to the station.\"",
        truths: ("A bolt cutter was found in {DL}'s car.", "The chain was already cut before {DL} arrived, per the station's own report."),
        defendant: [.direct("Did you read the notice the station gave you?", "\"Yes, I did read it. I knew I was not supposed to go onto that property.\""),
               .direct("Why did you climb the tower?", "\"It started as a dare from a friend. I thought it would be a quick climb, and I wanted to prove I could do it.\""),
               .direct("How did you get into the fenced area?", "\"The gate was open when I got there. I did not cut or break anything, and I walked right in.\""),
               .direct("What happened when you were up there?", "\"I froze about eighty feet up. The wind picked up, my hands shook, and I could not climb up or down.\""),
               .direct("How did you feel when the firefighters arrived?", "\"Terrified, and then very embarrassed. I am grateful to them for staying calm and getting me down safely.\""),
               .direct("What do you regret?", "\"I should not have gone, and I knew it when I was standing at the bottom. I am sorry to the station and to the firefighters.\""),
               .cross("You had a written notice, didn't you?", "\"Yes, I did, and I had it in mind that night. I should have stayed away and gone home.\""),
               .cross("You were in this court before, in {PRIORDATE}, for {PRIOR}, weren't you?", "\"Yes, I was, and I should have known better than to put myself in that spot again.\""),
               .cross("A bolt cutter was found in your car, wasn't it?", "\"Yes, it was. It is from my work, and I did not use it that night, because the gate was already open.\""),
               .cross("The chain was closed when you got there, wasn't it?", "\"I thought the gate was open, and I did not look at the chain closely. I do not think it was fastened.\""),
               .cross("You climbed because of a dare, didn't you?", "\"Yes, because of a dare, and it was a stupid thing to do. I did not think about the danger to anyone else.\"")],
        openings: ("{D} had a written notice from {V} to stay off the radio station's property. One night {DL} climbed the tower behind the studio, froze eighty feet up, and had to be rescued by firefighters. Back in {PRIORDATE}, {DL} was in this court on {PRIOR}.", "The defense will present a person who found an open gate and climbed on a dare. The station's own report says the chain was already cut, and no one was hurt."),
        closings: ("A written notice, a chained gate, and a tower climb that took firefighters away from other calls. {D} knew {D.he} was not allowed on that property.", "An open gate, a dare, and a person who did no damage and asked for help. The State has not shown that {D} broke in or meant harm."),
        timeline: [(-60, "{V} gives {D} a written no-trespass notice."), (0, "Night: {D} climbs the radio tower and freezes eighty feet up."), (0, "Midnight: firefighters answer the call and begin a rescue."), (1, "{V} reviews the cost to the broadcast and the condition of the gate.")],
        identified: "A notice.",
        impact: "It cost us a rescue. Fire crews came out in the dark, and the station had to shut down part of its broadcast. We had told this person in writing to stay off the property. A bad dare could have killed someone, and it pulled firefighters away from other calls.",
        genders: ["D": .male])

    static let bananaTwo = SmallCases.make(
        key: "story.followup.bananaTwo",
        category: .property,
        headlines: ["Self-Checkout Shopper Again Charged With Skipping Scan", "Defendant From Earlier Case Flagged by Store Cameras Again"],
        law: "misdLarceny",
        spec: "Stole $64 in merchandise belonging to {V}, a retailer, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, loss prevention at a different grocery store watched {D} skip scanning five items at a self-checkout. {DL} says {D.he} was in a hurry and meant to scan them.",
        state: [E(.video, 3, "Store Camera", "{D} bags five items without scanning."), E(.document, 2, "Receipt", "$64 in unscanned items.")],
        defense: [E(.statement, 1, "Hurry", "{DL} says {D.he} was in a hurry.")],
        role: "Loss prevention officer",
        exam: [.direct("What is your job at the grocery store?", "\"I work loss prevention. I watch the floor and the cameras, and I handle anyone we think is leaving without paying for everything.\""),
               .direct("What drew your attention to {DL}?", "\"{D.He} was at a self-checkout with a full basket, and I noticed {D.he} was bagging items without a scanning motion. I moved to a spot where I could see the screen.\""),
               .direct("What did you see on the camera?", "\"{DL} bags five items without scanning them, one after another, and then pays for the rest and heads for the door. The clip is clear and runs about four minutes.\""),
               .direct("What was the value of those items?", "\"$64 in total, based on the receipt and the shelf prices. It includes bananas, a roast, and a few packaged items.\""),
               .direct("What did you do?", "\"I let {D.him} walk out the door, as we always do, and then stopped {D.him} in the lot. I told {D.him} who I was and asked {D.him} to come back inside.\""),
               .direct("How did {DL} react?", "\"{D.He} was quiet and polite, and {D.he} said {D.he} was in a hurry and meant to scan them. I called the sheriff's office and went over the footage with the deputy.\""),
               .direct("Why does this matter to the store?", "\"It is the same thing at every store: small amounts that add up over a year. My staff has to chase it, file reports, and come to court, and we would rather help customers.\""),
               .cross("{DL} says {D.he} was in a hurry, doesn't {D.he}?", "\"{D.He} said so to me out in the lot. Maybe so, but five items in a row is not what a hurry usually looks like.\""),
               .cross("Could the self-checkout have jammed?", "\"The machine did not show a jam in its log. I checked it afterward and it was working normally that day.\""),
               .cross("Did {DL} scan some items correctly?", "\"Yes, {D.he} scanned the rest of the basket, which is why I think the five were chosen. A person who forgets usually misses one or two, not five in a row.\""),
               .cross("Did you see {DL} try to hide anything?", "\"No, {D.he} did not hide anything. {D.He} was in plain view of the camera the whole time.\""),
               .cross("You stopped {DL} outside, not inside, correct?", "\"Yes, that is our policy, so there is no question about whether the person meant to pay. That is how we do it at every store.\"")],
        theory: ("{D} skipped scanning five items at a self-checkout and walked out with them.", "{D} was in a hurry, meant to scan everything, and skipped five items by mistake."),
        allocution: "\"I was in a hurry, and I meant to scan every item. I know I skipped five at that self-checkout, and I should have slowed down and checked the screen. I'm sorry to the store, and I'm sorry for the money I owe. Money has been tight, but that's no excuse, and I'll pay it back.\"",
        truths: ("{DL} scanned a cheaper item each time.", "The scanner was jammed."),
        defendant: [.direct("Did you skip scanning those items?", "\"Yes, I did, and I know it. I have no excuse for the five I did not scan.\""),
               .direct("Why did you skip them?", "\"I was in a hurry, and I meant to scan every one. Money has been tight, and I let the hurry decide for me.\""),
               .direct("Were you trying to take them?", "\"I was not trying to leave with anything I had not paid for. I should have slowed down and checked the screen.\""),
               .direct("Did the machine have any problems?", "\"It was slow, and it froze once. I got impatient and just started bagging.\""),
               .direct("What did you say to the loss prevention officer?", "\"I told {V.him} the truth, that I was in a hurry and meant to scan them. I did not argue, and I came back inside.\""),
               .direct("What will you do about it?", "\"I will pay back every dollar I owe. I am sorry to the store.\""),
               .cross("You bagged five items without scanning, didn't you?", "\"Yes, I did, and I know how that looks on camera. I cannot say that it was not wrong.\""),
               .cross("The camera shows you bagging them one after another, doesn't it?", "\"It does, and I am not going to argue with it. It was careless of me.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"I was, and I know that makes it hard to believe me. I did not plan this and I regret it.\""),
               .cross("You scanned a cheaper item each time, didn't you?", "\"I scanned what was in front of me, in the order I picked things up. I did not choose.\""),
               .cross("Money has been tight, hasn't it?", "\"It has, but that is no excuse. I should have put something back instead.\"")],
        openings: ("Loss prevention at a grocery store watched {D} bag five items at a self-checkout without scanning them, $64 in all. {DL} came to us once before: {PRIORDATE}, {PRIOR}. This time the store camera and the receipt tell the story.", "The defense will present a customer in a rush at a slow machine who scanned most of a basket correctly and walked in plain view of the camera. A careless checkout is not the same as meaning to steal."),
        closings: ("Five items bagged without a scan, $64 out the door, and a camera that did not blink. A hurry does not skip five in a row.", "A slow machine and a rushed customer who paid for most of the basket. The State has not shown that {D} meant to take what was not paid for."),
        timeline: [(0, "{D} reaches a self-checkout with a full basket and starts bagging."), (0, "The store camera records five items going into the bag without being scanned."), (0, "Loss prevention stops {D} in the lot after {D.he} walks out."), (1, "A deputy reviews the footage and the $64 receipt.")],
        identified: "Store camera.",
        impact: "Same thing, different store. We watched a customer skip five items at self-checkout, and it was sixty-four dollars of merchandise. Each time it's small, but it adds up across a year. The employees have to chase it and file the paperwork. We'd rather spend that time helping customers.",
        genders: ["D": .male])

    static let inflatablesYard = SmallCases.make(
        key: "story.followup.inflatablesYard",
        category: .property,
        headlines: ["Holiday Display Stolen From Yard Again", "Another Stolen Lawn Display Traced to Defendant From Earlier Case"],
        law: "misdLarceny",
        spec: "Stole a holiday display valued at $210 belonging to {V}, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s lighted holiday display disappeared overnight. A neighbor's camera showed {D} loading it into a pickup. {DL} says {D.he} found it on the curb.",
        state: [E(.video, 3, "Neighbor Camera", "{D} loads the display into a pickup."), E(.document, 2, "Receipt", "The display cost $210.")],
        defense: [E(.statement, 1, "Curb", "{DL} says it was on the curb.")],
        role: "Homeowner",
        exam: [.direct("What was in your yard?", "\"A lighted holiday display that we put up every December: a big inflatable scene with a string of lights and a sign. The neighbors come by to see it.\""),
               .direct("What happened to it?", "\"We went to bed with it up and woke up to find it gone. The yard was bare and only the stakes' holes were left.\""),
               .direct("What was it worth?", "\"$210. I have the receipt from when we bought it, and the receipt shows the date and the price.\""),
               .direct("How was the display secured?", "\"It was staked down with four metal stakes and tied off with cord. It was not just sitting on the lawn.\""),
               .direct("What did the neighbor's camera show?", "\"It shows {DL} backing a pickup to the edge of my yard in the middle of the night. {D.He} loads the display into the bed and drives off.\""),
               .direct("How did your family react?", "\"My children asked if Santa had taken it. We put up a camera and a lock afterward, and it has not felt the same.\""),
               .direct("Did you give anyone permission to take it?", "\"No. It was in the yard, staked down, and I never gave anyone permission to touch it.\""),
               .cross("{DL} says the display was on the curb, doesn't {D.he}?", "\"That is what I am told, but it was not on the curb. It was in the yard, staked down.\""),
               .cross("Could someone have moved it to the curb first?", "\"I suppose someone could have, but I did not move it, and I heard nothing that night.\""),
               .cross("Was the display visible from the street?", "\"Yes, it is meant to be. People drive by to see it in the evening.\""),
               .cross("Did a neighbor's teenager have anything to do with it?", "\"I know of no teenager. If one moved it, I have not heard that from anyone.\""),
               .cross("Did you ever speak to {DL}?", "\"No, I did not know {D.him} before that night, and I have never spoken with {D.him}. Everything I have comes from the neighbor's video.\"")],
        theory: ("{D} loaded a family's staked-down holiday display into a pickup in the middle of the night.", "{D} found the display on the curb and thought it was being thrown out."),
        allocution: "\"I found that display on the curb, and I loaded it into my truck, thinking it was being thrown out. I know now it belonged to a family, and I should have knocked on a door. I'm sorry to {V} and to the children who loved it. I'll bring it back and pay for any damage.\"",
        truths: ("{DL}'s garage had the display's stakes.", "A neighbor's teenager admitted pulling the display and leaving it by the curb."),
        defendant: [.direct("Did you take the display?", "\"I picked it up, yes. I found it on the curb, and I thought it was being thrown out.\""),
               .direct("Where exactly did you find it?", "\"At the curb, a few feet from the street, lying on its side. I did not see anything staked down.\""),
               .direct("What did you do with it?", "\"I loaded it into my truck. I meant to use it for my own place, and I did not think about asking anyone.\""),
               .direct("Why did you not knock on a door?", "\"It was the middle of the night and the house was dark. I assumed it had been put out for the trash.\""),
               .direct("What happened to it after that?", "\"It is in my garage. I never sold it or used it, and I will bring it back.\""),
               .direct("What do you want the family to know?", "\"I am sorry that I took it. I should have asked first, and I will bring it back and pay for any damage.\""),
               .cross("You picked it up from a yard, didn't you?", "\"I picked it up from the curb. That is what I believed at the time.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that is why you do not believe me. I did what I did out of carelessness, not greed.\""),
               .cross("The stakes from the display were in your garage, weren't they?", "\"Yes, some were, and they were with the display. They were tied on to the cord when I picked it up, and I put them in the truck with it.\""),
               .cross("You came in the middle of the night, didn't you?", "\"Yes, because I was coming home from work. It was the only time I passed that street.\""),
               .cross("You did not leave a note or ask anyone, did you?", "\"No, I did not, and I regret it. I should have knocked on a door.\"")],
        openings: ("A family woke up in December to find their lighted holiday display, worth $210 and staked down in the yard, gone. A neighbor's camera shows {D} loading it into a pickup, and {DL} had a case in this court in {PRIORDATE} over {PRIOR}.", "The defense will present a driver who found the display at the curb and took it for trash. A person who loads something into a truck in front of a neighbor's camera is not hiding a theft."),
        closings: ("The display was staked down in the yard, and the camera shows a pickup backed up to it in the middle of the night.", "A display at the curb, a dark house, and a person who did nothing to hide. The State has not shown that {D} knew it belonged to anyone."),
        timeline: [(0, "Night: a pickup backs up to {V}'s yard and a neighbor's camera records {D} loading the display."), (1, "{V} wakes to find the yard empty and the stakes pulled."), (1, "{V} reports the $210 loss to deputies."), (5, "A deputy finds the display's stakes in {D}'s garage.")],
        identified: "A neighbor's camera.",
        impact: "My kids loved it. We put that lighted display up every December, and the neighbors came to see it. We woke up and found it gone. My children asked if Santa had taken it. We've put up a camera and a lock, and it's not the same.",
        genders: ["D": .male])

    static let graveyardScene = SmallCases.make(
        key: "story.followup.graveyardScene",
        category: .publicOrder,
        headlines: ["Man Disrupts Graveside Service, Deputy Called", "Defendant From Earlier Funeral Disturbance Back at Cemetery"],
        law: "disorderly",
        spec: "Disrupted a lawful assembly, a graveside service, by loud and abusive language, on {DATE}.",
        ages: 24...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} arrived at a graveside service for a family friend and shouted at the officiant for six minutes. A deputy removed {DL}. {DL} says grief overtook {D.him}.",
        state: [E(.statement, 3, "Officiant", "{D} shouted for six minutes."), E(.video, 2, "Cemetery Camera", "{D} approaches the tent.")],
        defense: [E(.statement, 1, "Grief", "{DL} says grief overtook {D.him}.")],
        role: "Officiant",
        exam: [.direct("What was your role at the cemetery that day?", "\"I was the officiant for the graveside service. A family had asked me to lead prayers and say a few words for a longtime friend of theirs.\""),
               .direct("What happened when the service began?", "\"About ten minutes in, {DL} walked up to the tent and began shouting at me. {D.He} said I had no right to speak and that the family had it wrong.\""),
               .direct("How long did the shouting last?", "\"About six minutes. I tried to continue, but {D.he} kept going, and the mourners could not hear the prayers.\""),
               .direct("How did the family react?", "\"They were in tears and some were angry. The widow asked me to stop and wait, and a nephew moved to put himself between {DL} and the casket.\""),
               .direct("What does the cemetery camera show?", "\"It shows {DL} coming across the lawn and approaching the tent. The shouting is on the audio.\""),
               .direct("What did the deputy do?", "\"The deputy asked {DL} to leave, and {D.he} went. The service resumed after about twenty minutes.\""),
               .direct("What did the family tell you about {DL}?", "\"They had told {DL} not to attend. They said {D.he} had been close to the deceased but there had been a falling out.\""),
               .cross("{DL} was grieving, wasn't {D.he}?", "\"I believe so. {D.He} was crying at times and was very upset.\""),
               .cross("Did {DL} threaten anyone?", "\"No, I did not hear a threat. It was loud and bitter, but it was not a threat.\""),
               .cross("Did {DL} touch anyone?", "\"No, {D.he} did not touch anyone or come near the casket. {D.He} stayed near the edge of the tent and kept {D.his} hands down.\""),
               .cross("Did {DL} leave when asked?", "\"Yes, {D.he} left when the deputy asked, without a fight or another word. {D.He} walked back across the lawn to {D.his} car.\""),
               .cross("You cannot say what {DL} felt, can you?", "\"No, I cannot. I can only tell you what I heard and saw, and what the family asked me to do.\"")],
        theory: ("{D} shouted at a graveside service for six minutes after the family told {D.him} not to come.", "{D} was overcome by grief at the burial of a close friend."),
        allocution: "\"I was overtaken by grief at that graveside, and I shouted at the officiant for far too long. The deceased was a close friend, and I couldn't hold it in. I had been told by the family not to attend, and I came anyway. I'm sorry to the family for ruining a service meant to be peaceful.\"",
        truths: ("{DL} had been told by the family not to attend.", "{DL} was close to the deceased."),
        defendant: [.direct("Did you shout at the service?", "\"Yes, I did. I was overcome by grief, and I could not hold it in.\""),
               .direct("Who was the deceased to you?", "\"A close friend, someone who had helped me through hard times. We had been friends for many years.\""),
               .direct("Had the family asked you not to attend?", "\"Yes, they had told me not to come. I came anyway because I could not stay away.\""),
               .direct("Why did you shout at the officiant?", "\"I was angry at what was being said, and I felt like the wrong people were speaking. I know now that I should have stayed quiet.\""),
               .direct("What did you do when the deputy came?", "\"I left. I walked to my car, and I sat there and cried.\""),
               .direct("What do you want the family to know?", "\"I am sorry for ruining a service meant to be peaceful. I will never forgive myself for that.\""),
               .cross("You shouted for six minutes, didn't you?", "\"It felt shorter, but I will not argue with the camera. I know it went on too long.\""),
               .cross("You were told not to come, weren't you?", "\"Yes, I was, and I should have honored that. I let my feelings take over.\""),
               .cross("You were in this court before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, I was, and that does not change that I loved my friend. It also does not excuse what I did.\""),
               .cross("The mourners could not hear the prayers, could they?", "\"I understand they could not, and that is what troubles me most.\""),
               .cross("You did not stop when the family asked you to, did you?", "\"No, I did not, and I regret it deeply. I heard the widow ask me to stop and I kept going anyway.\"")],
        openings: ("{D} came to a graveside service after the family had asked {D.him} not to, walked up to the tent, and shouted at the officiant for six minutes while mourners wept. {DL} was in this court before, in {PRIORDATE}, over {PRIOR}.", "The defense will present a close friend of the deceased who was overcome by grief. Mourning is not a plan to disrupt, and the shouting stopped when a deputy asked."),
        closings: ("Six minutes of shouting over a casket, after the family had said no, while widows and children listened. A cemetery camera recorded every minute of it, and {D} left only when a deputy came.", "Grief spoke that day, not a plan to disturb anyone. {D} left when asked, and the State has not shown an intent to disrupt the service."),
        timeline: [(0, "2 p.m.: the graveside service begins."), (0, "2:10 p.m.: {D} walks up to the tent and begins shouting at the officiant."), (0, "2:16 p.m.: a deputy arrives and asks {D} to leave."), (0, "2:20 p.m.: {D} leaves and the service resumes.")],
        identified: "The officiant.",
        mood: .sympathetic,
        genders: ["D": .male])

    static let witnessThreatLetter = SmallCases.make(
        key: "story.followup.witnessThreatLetter",
        category: .publicOrder,
        headlines: ["Threatening Letter Sent to Bar Witness Before Trial", "Defendant From Earlier Case Accused of Contacting Witness"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, a witness in {D}'s earlier case, on {DATE}.",
        ages: 21...48,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the bartender who had testified received an unsigned letter that said 'You'll pay for talking.' A prison mailroom record linked the stamp to {D}'s associate. {DL} says {D.he} had nothing to do with the letter.",
        state: [E(.document, 3, "Letter", "'You'll pay for talking.' mailed three days after the verdict."), E(.digital, 2, "Phone Records", "{D} called the sender five times.")],
        defense: [E(.statement, 1, "Not Mine", "{DL} says {D.he} didn't write or send the letter.")],
        role: "Bartender",
        exam: [.direct("What is your job?", "\"I tend bar at a neighborhood place. I work evenings, and I have worked there for six years.\""),
               .direct("Why did you testify in {DL}'s earlier case?", "\"I was a witness to what happened in the bar that night. I told the court what I saw, and the verdict was read three days before the letter.\""),
               .direct("What did the letter say?", "\"An unsigned note that said you will pay for talking. It had no return address and was mailed three days after the verdict.\""),
               .direct("How did you feel when you read it?", "\"Afraid. I read it standing at my mailbox, and then I went inside and locked the door.\""),
               .direct("What did the postmark and the stamp show?", "\"A prison mailroom record links the stamp to someone who is an associate of {DL}. That is what the detective told me.\""),
               .direct("What did you do?", "\"I saved the letter in a bag and called the sheriff's office. I gave the detective the envelope.\""),
               .direct("How has this changed your life?", "\"I will not work late shifts now. I changed my route home and asked my manager for day hours, and I still look over my shoulder.\""),
               .cross("The letter was not signed, was it?", "\"No, it had no name and no return address. All it had was one sentence in block letters on a plain sheet of paper.\""),
               .cross("Does the letter name {DL}?", "\"It does not. It says only that I will pay for talking.\""),
               .cross("Can you say who wrote it?", "\"No, I cannot say. I know only what the detective told me about the stamp.\""),
               .cross("Did {DL} ever contact you directly?", "\"No, not once. I have not heard from {D.him} since the trial.\""),
               .cross("You never saw anyone deliver it, did you?", "\"No, I found it in my mailbox with the other mail. I did not see who put it there or when.\"")],
        theory: ("{D} had a friend threaten the bartender who testified against {D.him}.", "{D} had nothing to do with the letter and does not know who wrote it."),
        allocution: "\"I had nothing to do with that letter. I did not write it, I did not send it, and I do not know who did. I've spoken to my lawyer about it. I'm sorry that the bartender was scared, and I hope whoever wrote it is found. I'd never try to frighten anyone who told the truth.\"",
        truths: ("{DL} had given a friend the bartender's address.", "The friend wrote and mailed the letter without {DL}'s knowledge."),
        defendant: [.direct("Did you write that letter?", "\"No, I did not. I had nothing to do with it.\""),
               .direct("Did you send it or ask anyone to?", "\"No. I do not know who did, and I have told the detective that.\""),
               .direct("Why did you call the sender five times?", "\"I called a friend, who is also the person whose stamp is on the letter, about my case. We talked about the trial and what comes next.\""),
               .direct("Did you discuss the bartender with your friend?", "\"I may have mentioned the bartender's name once, when we talked about the trial. I never asked anyone to do anything about it.\""),
               .direct("How do you feel about the letter?", "\"I am sorry the bartender was scared. I hope whoever wrote it is found.\""),
               .direct("What do you want the court to know?", "\"I would never try to frighten someone who told the truth. I have spoken to my lawyer, and I want this cleared up.\""),
               .cross("You called that friend five times after the verdict, didn't you?", "\"Yes, I did. We are close, and I was upset about the verdict.\""),
               .cross("That friend is the associate whose stamp was on the letter, isn't it?", "\"That is what they say. I did not know about the letter.\""),
               .cross("You had the bartender's address, didn't you?", "\"I may have had it, since it came up in the case. I did not give it to anyone for this.\""),
               .cross("You were in this court before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I am not proud of it. That is why I would not risk another case.\""),
               .cross("You did not tell the detective about the calls, did you?", "\"I told the detective I talked to my friend. I did not think the number of calls mattered, because we are close and talk often.\"")],
        openings: ("Three days after {D}'s verdict, the bartender who had testified received an unsigned letter that said you will pay for talking. A prison mailroom record ties the stamp to an associate of {D}, and phone records show {DL} called that person five times, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will present a person who did not write the letter, did not send it, and does not know who did. A friend's stamp and a few phone calls do not prove a threat."),
        closings: ("A threat, a stamp tied to {D}'s associate, and five calls to that person after the verdict. The bartender has been afraid ever since.", "An unsigned letter, a friend's stamp, and a few phone calls between friends. The State has not shown that {D} wrote or sent it, or asked anyone to."),
        timeline: [(0, "The verdict in {D}'s earlier case is read."), (3, "The bartender receives the unsigned letter."), (4, "The bartender reports it and hands the envelope to a detective."), (10, "A prison mailroom record links the stamp to an associate of {D}.")],
        identified: "The bartender.",
        mood: .wantsConviction,
        impact: "I won't work late shifts now. After I testified, I got an unsigned letter saying I'd pay for talking. The stamp traced to a prison mailroom. I changed my route home and asked my manager for day hours. I did what a citizen should, and I'm still looking over my shoulder.",
        genders: ["D": .male, "V": .male])

    static let dwlrAfterCrash = SmallCases.make(
        key: "story.followup.dwlrAfterCrash",
        category: .traffic,
        headlines: ["Driver in School Zone Crash Caught Driving While Revoked", "Defendant From Crossing Guard Case Stopped Behind the Wheel"],
        law: "dwlr",
        spec: "Operated a motor vehicle on a highway while {D.his} license was revoked, on {DATE}.",
        ages: 20...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}'s license had been revoked. A trooper stopped {DL} driving to a store. {DL} says {D.he} thought a limited privilege applied.",
        state: [E(.document, 3, "DMV Record", "An active revocation."), E(.statement, 2, "Trooper", "{D} said {D.he} thought a limited privilege applied.")],
        defense: [E(.statement, 1, "Privilege", "{DL} says {D.he} thought a limited privilege applied.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What is your assignment?", "\"I am a state trooper assigned to this district. I make traffic stops, work crashes, and run license checks, and I have done it for ten years.\""),
               .direct("Why did you stop {DL}?", "\"I saw {D.him} driving toward a store, and the plate came back to a driver whose license was revoked. I pulled in behind the car and activated my lights.\""),
               .direct("What did the DMV record show?", "\"An active revocation from the crash case. There was no limited driving privilege on file.\""),
               .direct("Was a limited privilege ever applied for?", "\"No application was in the record. The DMV shows nothing was filed.\""),
               .direct("What did {DL} tell you?", "\"{D.He} said {D.he} thought a limited privilege applied. {D.He} said a clerk told {D.him} one would be granted.\""),
               .direct("Why does this matter to you?", "\"The earlier crash was in a school zone full of children, and a crossing guard was hurt. I want the people near that school to be safe.\""),
               .direct("What did you do?", "\"I issued a citation for driving while license revoked and told {D.him} not to drive until it is resolved.\""),
               .cross("Did {DL} seem to believe a privilege applied?", "\"{D.He} said so. I cannot say what was in {D.his} mind.\""),
               .cross("Was {DL} driving to a store?", "\"Yes, a store a short way down the road. It was not far.\""),
               .cross("Did {DL} drive unsafely?", "\"No, the driving was normal. The only issue was the license.\""),
               .cross("Could a clerk have told {DL} a privilege was coming?", "\"It is possible. I have no way to know what a clerk said.\""),
               .cross("You never saw an application, did you?", "\"No, I did not, and the DMV record shows none. I cannot say what was said to {DL} at any counter.\"")],
        theory: ("{D} drove while {D.his} license was revoked after a crash in a school zone.", "{D} believed a limited privilege covered a short trip to a store."),
        allocution: "\"I thought I could drive on a limited privilege, because a clerk told me one would be granted. I was only driving to a store. I know now I had never filed for it, and I should have checked. I'm sorry for the crash that got me here and for driving while revoked.\"",
        truths: ("{DL} had never filed for a privilege.", "A clerk's note shows {DL} was told a limited privilege would be granted."),
        defendant: [.direct("Did you know your license was revoked?", "\"Yes, I knew it had been revoked after the crash. I thought I could drive on a limited privilege.\""),
               .direct("Why did you think that?", "\"A clerk told me one would be granted. I took it to mean I could drive while it was processed.\""),
               .direct("Did you file for it?", "\"I thought the clerk was handling it, and I did not check.\""),
               .direct("Why were you driving that day?", "\"I was going to a store a short way down the road. It was a short trip, and I did not think about it.\""),
               .direct("What do you remember about the stop?", "\"The trooper was polite. I told the truth about what I thought.\""),
               .direct("What do you regret?", "\"I regret the crash and I regret driving. I am sorry I did not check first.\""),
               .cross("You knew your license was revoked, didn't you?", "\"Yes, I knew, and I should not have driven at all. I thought the privilege would cover me.\""),
               .cross("You never filed an application, did you?", "\"No, I did not file, and that was my mistake. I assumed it was done.\""),
               .cross("A clerk's note shows you were told a privilege would be granted, doesn't it?", "\"There is a note, I understand. It says a clerk told me one would be granted.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"I was, and I know how it looks. I should have been much more careful than I was.\""),
               .cross("A school zone crash is why you were revoked, isn't it?", "\"Yes, and I think about the children and the crossing guard often.\"")],
        openings: ("{D}'s license was revoked after a crash in a school zone, and there is no limited privilege on file. A trooper stopped {DL} driving to a store, and {DL} had a case in this court in {PRIORDATE} over {PRIOR}.", "The defense will present a driver who was told by a clerk that a privilege would be granted and who drove only to a nearby store. A mistake about paperwork is not a defiance of the revocation."),
        closings: ("A revocation on the record, no privilege filed, and a driver on the road. The crash that caused it hurt a crossing guard.", "A clerk's note, a short drive to a store, and an honest answer to the trooper. The State has not shown that {D} knew the license was not good."),
        timeline: [(-300, "{D}'s license is revoked after a crash in a school zone."), (0, "A trooper stops {D} driving to a store."), (0, "The DMV record shows an active revocation and no privilege."), (0, "The trooper cites {D} for driving while license revoked.")],
        identified: "Trooper stop.",
        impact: "After a crash like that, I never want to see the same driver back on the road without a license. The school zone was full of children when it happened, and the crossing guard has not been the same. I stopped this driver again on the way to a store. I want the people near that school to feel safe.")

    static let stolenSafeResale = SmallCases.make(
        key: "story.followup.stolenSafeResale",
        category: .property,
        headlines: ["Safe From Home Invasion Resurfaces at Pawn Shop", "Stolen Safe Traced to Defendant From Burglary Case"],
        law: "possStolen",
        spec: "Possessed a safe belonging to {V}, knowing it to be stolen, on {DATE}.",
        ages: 20...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a stolen safe was recovered in a storage unit rented in {D}'s name. {V}'s name was engraved on the door. {DL} says {D.he} stored it for a cousin.",
        state: [E(.document, 3, "Storage Rental", "A unit rented in {D}'s name."), E(.physical, 3, "Safe", "{V}'s name engraved on the door.", .search)],
        defense: [E(.statement, 1, "Cousin", "{DL} says a cousin asked {D.him} to store it.")],
        role: "Homeowner",
        exam: [.direct("What was taken from your home?", "\"A safe that I kept in a closet. It held my late husband's papers, my mother's jewelry, and the deed to our house.\""),
               .direct("How do you know the safe is yours?", "\"My name is engraved on the door, which my husband had done years ago. I also have the receipt and a photo of it in the closet.\""),
               .direct("Where was it found?", "\"In a storage unit that was rented in {DL}'s name. A storage manager noticed it and called the sheriff's office.\""),
               .direct("What condition was it in?", "\"It had been stripped and left. The jewelry and papers were gone.\""),
               .direct("What does the storage rental show?", "\"A rental in {D}'s name with a card on file. It was opened a few days after the theft.\""),
               .direct("How has this affected you?", "\"I cannot replace those photographs and papers. I just want what is left.\""),
               .direct("Do you know {DL}?", "\"No, I do not. I have never met {D.him}, and I never gave {D.him} anything.\""),
               .cross("{DL} says the safe belonged to a cousin, doesn't {D.he}?", "\"That is what I have heard. It was my safe, with my name on the door.\""),
               .cross("Could someone else have rented the unit in {DL}'s name?", "\"I do not know. That is a question for the storage company.\""),
               .cross("Did you see anyone take the safe?", "\"No, I did not. I was away at my sister's for the weekend, and I came home to a closet that was empty.\""),
               .cross("Has the cousin been identified?", "\"Nobody has given me a name, and I do not know whether the deputies have found such a person.\""),
               .cross("You do not know who put the safe in the unit, do you?", "\"No. I know only that it was in a unit in {D.his} name.\"")],
        theory: ("{D} kept a stolen safe in a storage unit rented in {D.his} own name.", "{D} stored a safe for a cousin who used {D.his} card and never told {D.him} where it came from."),
        allocution: "\"That safe belonged to my cousin, and I stored it for my cousin without knowing where it came from. My cousin took my card number and rented the unit online, and I had no record of it. I'm sorry that {V}'s property was found in a unit in my name. I'll cooperate however I can.\"",
        truths: ("{DL}'s cousin had no storage record.", "The cousin had taken {DL}'s card number and rented the unit online."),
        defendant: [.direct("Whose safe was that?", "\"It belonged to my cousin. I stored it for my cousin and I did not know where it came from.\""),
               .direct("Did you know it was stolen?", "\"No, I did not. I never would have kept it if I had.\""),
               .direct("Did you rent the storage unit?", "\"My name is on it, but my cousin took my card number and rented the unit online. I had no record of it.\""),
               .direct("When did you learn about it?", "\"When a deputy called me about the unit. I was shocked, and I did not even understand what I was being told at first.\""),
               .direct("Have you spoken to your cousin since?", "\"I tried, but my cousin does not answer. I do not know where my cousin is.\""),
               .direct("What do you want the court to know?", "\"I am sorry that {V}'s property was found in a unit in my name. I will cooperate however I can.\""),
               .cross("Your name is on the lease, isn't it?", "\"Yes, it is, and that is part of what troubles me. My cousin used my details, and I only learned of it when the deputy called.\""),
               .cross("You never saw the safe, did you?", "\"I saw it once, in my cousin's car. I did not look inside.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, I was, and I know it hurts my credibility. That does not make me the one who took it.\""),
               .cross("Your cousin has never been named to the deputies, has he?", "\"I gave a name. They said they could not find anyone by it.\""),
               .cross("You paid for the unit, didn't you?", "\"No, I did not pay for it. The card number was used without my knowledge, and I found out only from the statement.\"")],
        openings: ("A safe engraved with {V}'s name was stolen from a closet and found in a storage unit rented in {D}'s name. The rental was opened days after the theft, and {DL} had a case in this court in {PRIORDATE} over {PRIOR}.", "The defense will present a cousin who took {D}'s card number and rented the unit online. A name on a lease is not proof of who carried the safe in."),
        closings: ("The safe was in {D}'s unit, under {D}'s name, with {V}'s name engraved on the door. A rental opened days after the theft is not a coincidence, and the cousin has never been named.", "A cousin with a card number and a name no one can find. The State has not shown that {D} knew the safe was stolen."),
        timeline: [(0, "{V}'s safe is taken from a closet while {V} is away."), (2, "A storage unit is rented in {D}'s name online."), (10, "A storage manager reports a safe in the unit to deputies."), (10, "A deputy opens the unit and finds {V}'s name engraved on the door.")],
        identified: "Storage unit.",
        mood: .wantsConviction,
        impact: "I want my things back. That safe held my late husband's papers, my mother's jewelry, and the deed to our house. When we found it, it had been stripped and left in a rented storage unit. I can't replace those photographs, and I just want what's left.")

    static let insuranceFireClaim = SmallCases.make(
        key: "story.followup.insuranceFireClaim",
        category: .whiteCollar,
        headlines: ["Fire Victim Files Inflated Insurance Claim", "Insurance Fraud Charge Names Defendant From Fire Case"],
        law: "insuranceFraud",
        spec: "Presented a false statement in support of an insurance claim, on {DATE}.",
        ages: 24...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, an insurer found {D}'s renter's claim listed a $9,000 television and jewelry that never existed. {DL} says the list was prepared by an assistant.",
        state: [E(.document, 3, "Claim Form", "A $9,000 television and jewelry listed."), E(.document, 2, "Adjuster Report", "No such items in the photos.")],
        defense: [E(.statement, 1, "Assistant", "{DL} says an assistant prepared the list.")],
        role: "Insurance adjuster",
        exam: [.direct("What is your job with the insurance company?", "\"I am a claims adjuster. I review renter's claims after fires and burglaries, and it is my job to decide what we can verify and what we cannot.\""),
               .direct("What did {DL}'s claim list as destroyed in the fire?", "\"A $9,000 television and a group of jewelry pieces, among many other items. Those two entries were the largest on the whole list.\""),
               .direct("What did you find when you reviewed the apartment?", "\"The photos taken after the fire show no television and no jewelry. There was no melted frame, no ash that looked like electronics, and nothing in the debris matching those entries.\""),
               .direct("Did {DL} give you receipts or earlier photographs?", "\"No receipts, no serial numbers, and no photographs from before the fire. The only record of those items is the claim list itself.\""),
               .direct("Who signed the claim?", "\"{DL} signed every page. The last page has a statement that the information is true to the best of the signer's knowledge, and it carries {D.his} signature.\""),
               .direct("What did {DL} tell you about the list?", "\"{D.He} said an assistant helped prepare it and that {D.he} did not check it closely. When I asked who the assistant was, {D.he} did not give me a name.\""),
               .direct("What happened to the claim?", "\"We denied the items we could not verify and referred the file to the sheriff's office. The real fire damage to the unit was handled separately and paid.\""),
               .cross("Was there a real fire in {DL}'s apartment?", "\"Yes, there was. Part of the unit was badly damaged, and we paid to repair it without any question about that portion.\""),
               .cross("Did {DL} lose belongings in the fire?", "\"Yes, some things were destroyed, and the photos show burned furniture and clothing. That part of the claim was never in dispute.\""),
               .cross("Is it possible a television could be destroyed completely?", "\"Sometimes very little is left. But the photos show where the television stand was, and there was nothing there that looked like a television.\""),
               .cross("Did your office pre-fill any part of the form?", "\"Our office pre-fills the policy details at the top. The list of items was written by the policyholder or someone helping, not by us.\""),
               .cross("You do not know who actually wrote the list, do you?", "\"No, I do not. {DL} would not give a name, so all I can tell you is whose signature is on every page.\"")],
        theory: ("{D} padded a fire claim with a $9,000 television and jewelry that never existed.", "{D} signed a list prepared by an assistant without checking it."),
        allocution: "\"I signed that claim, and I did not check the list, because an assistant prepared it. I know my signature is on every page. I'm sorry that it included a television and jewelry that did not exist. I lost much in the fire, and I should have read every line. I'll correct the claim and repay anything paid.\"",
        truths: ("{DL}'s signature was on every page.", "The adjuster's pre-filled list was signed without a close check."),
        defendant: [.direct("Did you sign the claim?", "\"Yes, I signed it, and I know my signature is on every page. I will not say otherwise.\""),
               .direct("Did you read the list before you signed?", "\"No, I did not check it closely. An assistant had prepared it, and I was exhausted and trusted that the work was right.\""),
               .direct("Was there a television in your apartment?", "\"I owned one, but it was nowhere near $9,000. I cannot explain how that number got onto the list.\""),
               .direct("What did you lose in the fire?", "\"A great deal. Clothes, furniture, papers, and keepsakes from my family. It was a very hard time for me, and I was not thinking clearly.\""),
               .direct("Who was the assistant?", "\"A person who helped me with paperwork after the fire. I did not want to get that person in trouble, but I will give the name to the court.\""),
               .direct("What will you do about the claim?", "\"I will correct it and repay anything that was paid on those items. I am sorry that a mistake of mine caused so much trouble.\""),
               .cross("You signed a claim for a $9,000 television that did not exist, didn't you?", "\"I signed it without checking the list, and I know that was wrong. I should have read every line before I put my name on it.\""),
               .cross("You have a prior case in this court from {PRIORDATE}, don't you?", "\"Yes, and I know that makes this look worse. I did not do this on purpose, and I hope the court will consider that.\""),
               .cross("You have no receipt for the jewelry, do you?", "\"No, I do not. A lot was lost in the fire, and the papers that would have shown what I owned burned with everything else.\""),
               .cross("The list was signed without a close check, wasn't it?", "\"Yes, that is exactly what happened. I was overwhelmed that week, and I trusted what was put in front of me.\""),
               .cross("You would not name the assistant when the adjuster asked, would you?", "\"I did not want to hurt someone who was only trying to help me. I now understand that was a mistake and I will give the name.\"")],
        openings: ("After an apartment fire, {D} filed a renter's claim listing a $9,000 television and jewelry, and the adjuster's photos show nothing like them in the debris. {DL} signed every page, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a person who lost a great deal in a fire and signed a list that an assistant prepared. A careless signature in the middle of a disaster is not a plan to defraud an insurer."),
        closings: ("Every page carries {D}'s signature, the list includes items the photographs do not, and no receipt exists for any of it. A claimant who signs owns what is on the page.", "A fire, an exhausted claimant, and a list prepared by someone else. The State has not shown that {D} knew the television and jewelry were false when {D.he} signed."),
        timeline: [(-14, "An apartment fire damages {D}'s unit."), (0, "{D} files a renter's claim listing a $9,000 television and jewelry, signed on every page."), (7, "The adjuster reviews the photographs and finds no sign of the listed items."), (10, "The insurer refers the claim to the sheriff's office.")],
        identified: "The claim form.",
        impact: "Fraud raises everyone's rates. I've handled claims for twenty years, and honest families who suffer real fires pay more because of padded lists. This one included a nine-thousand-dollar television that never existed. We check every claim, and every false one costs us hours. I'd like to see honest customers treated fairly.")

    static let stalkingCourtOrderAbduction = SmallCases.make(
        key: "story.followup.stalkingCourtOrderAbduction",
        category: .family,
        headlines: ["No-Contact Order Violated by Defendant From Abduction Case", "Defendant Seen Near Victim's Workplace in Violation of Order"],
        law: "stalkingCourtOrder",
        spec: "Willfully stalked {V}, in violation of a court order, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a no-contact order barred {D} from {V}. {V} saw {DL}'s van near {V.his} workplace three times in one week. {DL} says {D.he} drove that road to work.",
        state: [E(.document, 3, "Order", "A no-contact order served on {D}."), E(.video, 3, "Workplace Camera", "{D}'s van passes three times.")],
        defense: [E(.statement, 1, "Commute", "{DL} says it is on {D.his} way to work.")],
        role: "Victim",
        exam: [.direct("Why do you have a no-contact order against {DL}?", "\"I obtained it after the first case in this court. I needed to be able to breathe again, and the court granted it so that {D.he} could not approach me.\""),
               .direct("Was {DL} served with that order?", "\"Yes. A deputy served it, and I have the return of service in my file. {D.He} knew exactly what it said.\""),
               .direct("What did you see near your workplace?", "\"A white van, three times in one week. I saw it on Monday, Wednesday, and Friday, each time on the road in front of the building.\""),
               .direct("What does the workplace camera show?", "\"It shows the van passing the front gate three times at about the same hour each day. The plate matches {DL}'s van, and I saw {D.him} through the window once.\""),
               .direct("How did you react?", "\"I changed my schedule, I park inside the gate now, and I told my supervisor. I flinch every time I see a van with a ladder rack.\""),
               .direct("Is that road on {DL}'s route to work?", "\"I do not believe so. {D.His} job is across town, in the opposite direction from my workplace, and I have known that for a long time.\""),
               .direct("How has this affected your life?", "\"I live in fear. I wake up early, I check the lot before I leave the car, and I have not relaxed since I first saw that van.\""),
               .cross("It is a main road, isn't it?", "\"It is a public road, yes, and many people use it. But the van passed my building three times in one week.\""),
               .cross("Could {DL} have been on the way to work?", "\"That is what {D.he} says, but {D.his} work is not that way. The van passed three times, which is not how a commute usually goes.\""),
               .cross("Did {DL} stop or get out of the van?", "\"No, {D.he} did not stop or get out. The van only drove past each time, and nobody approached me.\""),
               .cross("Did you see {DL}'s face each time?", "\"I saw the van each time and {D.his} face once through the window. The other times I am relying on the plate and the camera.\""),
               .cross("Could it have been a different white van?", "\"The plate matches {DL}'s van, and I am certain about that. There may be other white vans, but this one has the same plate.\"")],
        theory: ("{D} drove past {V}'s workplace three times in one week despite a no-contact order.", "{D} took a shortcut to {D.his} job and did not know it passed {V}'s workplace."),
        allocution: "\"I drove that road to work, and it was a commute and a shortcut, not a search for anyone. My employer is across town in the opposite direction from {V}'s workplace, and I didn't know it was so close. I know about the order. I'm sorry for the fear, and I'll take a different route.\"",
        truths: ("{DL}'s employer is across town in the opposite direction.", "The van passing {V}'s workplace was a different white van with a ladder rack, per its plate."),
        defendant: [.direct("Did you drive past {V}'s workplace?", "\"Yes, I drove that road, three times in that week according to the camera. It is a shortcut I take on the way to work.\""),
               .direct("Why did you take that road?", "\"It saves me about ten minutes in the morning, and I use it when the highway backs up. I did not know it passed {V}'s workplace.\""),
               .direct("Did you know about the no-contact order?", "\"Yes, I knew about the order, and I have tried to follow it carefully. I have not called or written or gone near {V.him}.\""),
               .direct("Were you looking for {V}?", "\"No. I never wanted to see {V.him} again, and I did not follow {V.him} or watch the building.\""),
               .direct("Why did you not stop using that road once you noticed?", "\"I did not notice at first, and then I thought it would look worse if I suddenly changed. I know that was foolish.\""),
               .direct("What will you do now?", "\"I will take a different route from now on, even if it costs me time. I am sorry for the fear I caused.\""),
               .cross("Your employer is across town in the opposite direction, isn't it?", "\"Yes, and that road is only a shortcut I take sometimes. I did not think of it as going toward {V.him}.\""),
               .cross("You passed three times in one week, didn't you?", "\"Yes, because I take that route to work most days. I did not know {V.he} worked there.\""),
               .cross("You were in this court before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that the order came from that case. I do not want any contact, and I never did.\""),
               .cross("Your van has a ladder rack, doesn't it?", "\"Yes, it does, and so do many work vans. I use mine for my job every day.\""),
               .cross("You never stopped at the building, did you?", "\"No, I did not. I never stopped, got out, or spoke to anyone, and the camera shows that.\"")],
        openings: ("A no-contact order bars {D} from {V}. In one week, a workplace camera recorded {DL}'s van passing {V}'s building three times, and {V} has been afraid ever since, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a driver whose shortcut to work happens to pass that building. A drive on a public road, with no stop and no contact, is not stalking."),
        closings: ("An order served on {D}, a van with a ladder rack, and three passes in five days on a road that is not on {D.his} way to work.", "A public road, a shortcut, and a van that never stopped. The State has not shown that {D} was looking for {V}, only that {D.he} drove past."),
        timeline: [(-30, "The no-contact order is served on {D}."), (0, "Monday: the workplace camera records {D}'s van passing {V}'s building."), (2, "Wednesday: the van passes again at about the same hour."), (4, "Friday: the van passes a third time, and {V} reports it to deputies.")],
        identified: "Workplace camera.",
        mood: .wantsConviction,
        impact: "I live in fear. I obtained that no-contact order so I could breathe again. Then I saw a white van near my workplace three times in one week. I rearranged my schedule and park inside the gate. I flinch every time I see a van with a ladder rack.",
        genders: ["D": .male, "V": .female])

    static let pillMillAgain = SmallCases.make(
        key: "story.followup.pillMillAgain",
        category: .drugs,
        headlines: ["Defendant From Overdose Case Charged With New Sale", "Undercover Buys Pills From Defendant"],
        law: "deliverSchedII",
        spec: "Delivered a Schedule II controlled substance on {DATE}.",
        ages: 20...40,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, an undercover agent bought 12 pills from {D} for $240. Testing showed fentanyl again. {DL} says the pills were prescribed to {D.him}.",
        state: [E(.video, 3, "Undercover Recording", "{D} hands over 12 pills for $240."), E(.forensic, 3, "Lab Report", "Fentanyl in the pills.")],
        defense: [E(.statement, 1, "Prescribed", "{DL} says the pills were prescribed to {D.him}.")],
        role: "Drug task force agent",
        exam: [.direct("What is your assignment?", "\"I am an agent on a drug task force. I work undercover buys and write the case reports, and I have done that work for eight years.\""),
               .direct("What did {DL} sell you?", "\"Twelve pills for $240. I met {D.him} at a pre-arranged spot, and {D.he} handed them over in a small plastic bag.\""),
               .direct("What does your recording show?", "\"It shows the meeting, the hand-over, and the money passing between us. The audio is clear, and {D.he} says what the pills are.\""),
               .direct("What did the lab find?", "\"Fentanyl in the pills. The lab report says they are not what they were sold as, and they are extremely dangerous to anyone who takes them.\""),
               .direct("Did {DL} show you a prescription?", "\"No prescription was shown, and I checked the state database afterward and found none in {D.his} name.\""),
               .direct("What did {DL} say about the pills?", "\"{D.He} said they were prescribed to {D.him} and that {D.he} was sharing some. {D.He} did not say anything about what was in them.\""),
               .direct("Why does this case matter to you?", "\"Every pill like that is a death waiting to happen. I have been to too many funerals over it, and this was the same kind of pill from the same person.\""),
               .cross("Does your recording have a gap in it?", "\"There was a short cut-out when the recorder lost its signal. It was less than a minute, and the hand-over is on the recording either side of it.\""),
               .cross("Could {DL} have a prescription from another state?", "\"I did not find one. I checked what I could, but I cannot rule out a prescription I could not see.\""),
               .cross("Did {DL} know the pills held fentanyl?", "\"I cannot say what {D.he} knew. {D.He} did not mention fentanyl, and I did not ask.\""),
               .cross("Did you see {DL} make or press the pills?", "\"No, I did not. I only know that {D.he} handed them to me for money.\""),
               .cross("You cannot say where {DL} got them, can you?", "\"No, I cannot. How the pills reached {D.him} was not part of this investigation.\"")],
        theory: ("{D} sold pills containing fentanyl to an undercover agent.", "{D} handed over pills {D.he} believed were prescribed and did not know what they held."),
        allocution: "\"Those pills were prescribed to me, and I thought I was allowed to share them. I know now that I wasn't, and I did not know what they held. I'm sorry for the harm they could cause. I'll take any program the court requires, and I won't pass medication to anyone again.\"",
        truths: ("No prescription exists for {DL}.", "The agent's recorder cut out."),
        defendant: [.direct("Did you hand over those pills?", "\"Yes, I did. I gave them to the agent for $240, and I will not pretend otherwise.\""),
               .direct("Why did you do it?", "\"I believed I was allowed to share them because they were prescribed to me. I also needed the money.\""),
               .direct("Were they prescribed to you?", "\"I believed so. I have had a prescription for pain in the past, and these looked like the ones I was given.\""),
               .direct("Did you know they held fentanyl?", "\"No, I did not. If I had known, I would never have touched them.\""),
               .direct("What did you say to the agent?", "\"I told the agent they were mine and that I did not need them anymore. I did not try to hide anything.\""),
               .direct("What will you do now?", "\"I will take any program the court requires. I will not pass medication to anyone again.\""),
               .cross("You sold twelve pills for $240, didn't you?", "\"Yes, I did, and I know it was wrong. I should not have taken money for medicine.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"I was, and I should have known better after that case. I let money problems get ahead of me.\""),
               .cross("No prescription exists in your name, does it?", "\"I thought I had one. I do not know why the agent could not find it, and I cannot prove it today.\""),
               .cross("The lab found fentanyl in what you sold, didn't it?", "\"Yes, and I am sorry for it. I did not know, and I would never have handed those over if I had.\""),
               .cross("You were paid in cash, weren't you?", "\"Yes, the agent paid me in cash at the meeting, and I put it in my pocket.\"")],
        openings: ("An undercover agent bought twelve pills from {D} for $240, and the lab found fentanyl in them. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the state database shows no prescription in {D.his} name.", "The defense will present a person who believed the pills were prescribed and did not know what was in them. Selling a pill is serious, but the State must prove that {D} knew what {D.he} was selling."),
        closings: ("The recording shows twelve pills handed over for $240, and the lab found fentanyl in them. {D} had been before this court on this same kind of charge.", "A pill that {D} believed was prescribed, a recording that cuts out, and a person who did not know what was in the bag. The State has not shown that {D} knew."),
        timeline: [(0, "An undercover agent buys twelve pills from {D} for $240 and records the meeting."), (5, "The lab tests the pills and finds fentanyl."), (6, "The agent checks the state database and finds no prescription for {D}.")],
        identified: "Undercover recording.",
        impact: "It wasn't over. After the first case, I thought this kind of pill was off our streets. Then I bought twelve more from the same person, and the lab found fentanyl in them again. Every pill like that is a death waiting to happen. I've been to too many funerals for it.",
        genders: ["D": .male])

    static let workplaceThreat = SmallCases.make(
        key: "story.followup.workplaceThreat",
        category: .publicOrder,
        headlines: ["Threat at New Workplace Follows Poisoning Case", "Defendant From Coffee Case Threatens Manager"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, a manager, on {DATE}.",
        ages: 26...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} told {V}, a new manager, 'You don't want to find out what I put in drinks.' A coworker heard it. {DL} says it was a joke.",
        state: [E(.statement, 3, "Coworker", "{D} said it to {V}."), E(.document, 2, "Incident Report", "Filed the same day.")],
        defense: [E(.statement, 1, "Joke", "{DL} says it was a joke.")],
        role: "Manager",
        exam: [.direct("What is your position at the restaurant?", "\"I manage the kitchen and the bar staff. I had taken over the team about three weeks before this happened, so I was still learning who everyone was.\""),
               .direct("What did {DL} say to you?", "\"In the middle of prep, with other staff around, {D.he} looked at me and said, You don't want to find out what I put in drinks. I heard every word.\""),
               .direct("How did you take it?", "\"As a threat. I was new to the team, and a person who handles the drinks had just told me I should be afraid of what goes into them.\""),
               .direct("Who else heard it?", "\"A coworker was standing a few feet away at the bar. {D.He} heard it too, and the two of us froze for a moment.\""),
               .direct("What did you do?", "\"I walked away, wrote down exactly what was said, and filed an incident report with the owner that same day. For the rest of that week I checked every cup before it went out.\""),
               .direct("How has this affected your work?", "\"It is hard to run a team when you are afraid of one of them. I felt uneasy every time I walked past the drinks station.\""),
               .cross("Was {DL} smiling when {D.he} said it?", "\"I did not see a smile. It was said flatly, and I could not tell what {D.he} meant by it.\""),
               .cross("Did a coworker start the what is in the drinks joke earlier?", "\"I did not hear anyone say that. If it was said before I arrived, nobody told me about it.\""),
               .cross("Did {DL} actually do anything to a drink?", "\"No, I am not aware of anything being done. Nothing was found when we checked, and no customer complained.\""),
               .cross("Did you ask {DL} what {D.he} meant?", "\"Not at the time. I walked away, because I did not want to make it worse in front of the staff.\""),
               .cross("You were new in this job when it happened, weren't you?", "\"Yes, about three weeks in. I did not know the team well, and I did not know {DL}'s sense of humor.\"")],
        theory: ("{D} told a new manager that {V.he} would not want to know what {D.he} puts in the drinks.", "{D} repeated a kitchen joke that a coworker had started and meant no harm."),
        allocution: "\"It was a joke, and I understand now that it was not funny. I told my new manager something about what I put in drinks, and I know how it sounded. I'm sorry that {V} heard it as a threat. I never meant to scare anyone, and I'll apologize in person.\"",
        truths: ("{DL} had joked about poisoning a coffee pot at the last job.", "A coworker started the 'what's in the drinks' joke minutes earlier."),
        defendant: [.direct("Did you say it?", "\"Yes, I said it. It was a joke, and I understand now that it was not funny.\""),
               .direct("Why did you say it?", "\"A coworker had been joking about what goes in the drinks just before, and I joined in without thinking. I was not trying to threaten the new manager.\""),
               .direct("Did you mean it as a threat?", "\"No, I never meant it as a threat. I never meant to scare anyone, and I would never do anything to a drink.\""),
               .direct("Have you made a joke like that before?", "\"I joked about a coffee pot at my last job. People laughed there, and I thought it was harmless, so I did not think before I said it here.\""),
               .direct("What happened after the manager reported it?", "\"I was suspended and told I would have to come to court. I felt terrible, because I like the job and the people.\""),
               .direct("What will you do about it?", "\"I will apologize to the manager in person. I am sorry that it was heard as a threat.\""),
               .cross("You told a new manager that {V.he} did not want to know what you put in drinks, didn't you?", "\"Yes, I said something like that, and I know how it sounded. I did not think about who was listening.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I should have thought before speaking, given that history. I know people hear me differently because of it.\""),
               .cross("You joked about poisoning a coffee pot at your last job, didn't you?", "\"Yes, I did, and it was a joke then too. I did not think it would follow me here.\""),
               .cross("You said it to someone who had just taken charge, correct?", "\"Yes, I did, and I should have known how it would land. I was careless with my words.\""),
               .cross("You did not apologize that day, did you?", "\"No, I did not, and I regret it. I was embarrassed and I walked off instead of saying I was sorry.\"")],
        openings: ("A few weeks after {V} became the manager of a restaurant kitchen, {D} told {V}, within earshot of a coworker, You don't want to find out what I put in drinks. {V} filed an incident report that same day, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a joke that a coworker began minutes earlier and that {D} repeated without thinking. A bad joke in a kitchen is not a threat to injure anyone."),
        closings: ("A coworker heard words that any listener would take as a threat, spoken to a new manager who handles the food and drink.", "It was a joke, and a coworker had started it. The State has not shown that {D} meant to frighten anyone or intended any harm."),
        timeline: [(0, "Morning prep: {D} tells {V} that {V.he} does not want to know what {D.he} puts in drinks."), (0, "A coworker standing a few feet away hears it."), (0, "Noon: {V} files an incident report with the owner.")],
        identified: "Coworker.",
        impact: "I took it seriously. A new manager walks into a kitchen, and one of the staff tells me I don't want to know what goes in drinks. A coworker heard it, and we both froze. I checked every cup that week. It's hard to run a team when you're afraid of one of them.")

    static let jailAssault = SmallCases.make(
        key: "story.followup.jailAssault",
        category: .violent,
        headlines: ["Detention Officer Struck During Intake", "Defendant From Party Case Faces New Assault Charge"],
        law: "assaultGovOfficial",
        spec: "Assaulted {V}, a detention officer, while the officer was discharging official duties, on {DATE}.",
        ages: 19...35,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, during an intake search, {D} swung at {V}, a detention officer. A camera shows the swing. {DL} says {D.he} flinched and did not mean to hit.",
        state: [E(.video, 3, "Intake Camera", "{D} swings at {V} during a pat-down."), E(.statement, 2, "Second Officer", "{D} yelled before swinging.")],
        defense: [E(.statement, 1, "Flinch", "{DL} says it was a flinch.")],
        role: "Detention officer",
        exam: [.direct("What is your job at the county jail?", "\"I am a detention officer. I work the intake area, where new arrivals are searched and processed before they go to a housing unit.\""),
               .direct("What happened during the intake search?", "\"I was patting {DL} down, the way I have done thousands of times, and a fist came toward my face. {D.He} swung at me.\""),
               .direct("Where did the blow land?", "\"I had a bruise there for several days, and my jaw was sore when I ate.\""),
               .direct("What does the intake camera show?", "\"It shows {DL} swinging during the pat-down. You can see the arm come up and across toward my head.\""),
               .direct("What did the second officer see?", "\"{D.He} says {DL} yelled just before swinging. I was concentrating on the search, so I did not catch every word.\""),
               .direct("What did you do after the blow?", "\"I stepped back, called for help, and the other officers restrained {D.him}. Nobody else was hurt.\""),
               .direct("How did it affect you?", "\"I was lucky to get away with a bruise. Every officer in that room felt the same jolt, and the rest of the shift was tense.\""),
               .cross("{DL} says it was a flinch, doesn't {D.he}?", "\"That is what {D.he} says. From where I stood, it did not look like a flinch to me.\""),
               .cross("Was your hand near {DL}'s neck?", "\"I was doing a standard pat-down, and my hand was near the collar, which is where a search starts. I did not choke or squeeze.\""),
               .cross("Had {DL} said anything to you before?", "\"Earlier in the intake, {D.he} said some things I did not like. I did not take them seriously at the time.\""),
               .cross("Was {DL} afraid?", "\"I could not tell. {D.He} seemed angry and tense, and it showed in how {D.he} stood.\""),
               .cross("You were not seriously hurt, were you?", "\"No, just a bruise and some soreness. I went back to work the next day.\"")],
        theory: ("{D} struck a detention officer during an intake search.", "{D} flinched during a pat-down and did not mean to hit the officer."),
        allocution: "\"I flinched during that search, and I swung without meaning to hit the officer. I was scared, and I didn't know what was happening. I'm sorry that {V} was struck. I know the officer was just doing a job, and I'll cooperate from here on.\"",
        truths: ("{DL} had threatened the officer earlier.", "The officer's hand was on {DL}'s neck."),
        defendant: [.direct("Did you swing at the officer?", "\"Yes, I swung. I flinched, and my arm went up before I knew what I was doing.\""),
               .direct("Why did you flinch?", "\"I was scared and did not know what was happening. The officer's hand was near my neck, and it felt like a grab.\""),
               .direct("Did you mean to hit the officer?", "\"No. I did not mean to hit anyone, and I never expected my arm to land.\""),
               .direct("Were you yelling?", "\"Yes, I was yelling. I was frightened, and I was trying to tell them to stop.\""),
               .direct("What happened after you swung?", "\"I was tackled and held down by several officers. I did not fight back, and I told them I was sorry.\""),
               .direct("What do you want the officer to know?", "\"I am sorry that {V.he} was struck. I know the officer was just doing a job, and I will cooperate from here on.\""),
               .cross("The camera shows you swing at the officer, doesn't it?", "\"It does, and I am not going to say it did not happen. I just did not mean for it to land on the officer.\""),
               .cross("You had threatened the officer earlier, hadn't you?", "\"I said some things when I was upset and scared. I did not mean any of them.\""),
               .cross("You had a case in this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I know how that looks to everyone in this room. It made me more afraid, not less.\""),
               .cross("Your swing landed on the officer's jaw, didn't it?", "\"Yes, and I am sorry for it. I did not know it landed until the officers told me.\""),
               .cross("You yelled before swinging, didn't you?", "\"Yes, I yelled, and I was scared. I was not trying to give a warning.\"")],
        openings: ("During an intake search at the county jail, {D} swung at {V}, a detention officer, and struck {V.him} on the jaw. A camera recorded it, a second officer heard yelling first, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a frightened person who flinched when a hand came near {D.his} neck. A reflex, even a bad one, is not an intentional assault on an officer."),
        closings: ("The video shows a swing during a routine pat-down, a second officer heard yelling before it, and {V} was struck on the jaw.", "A flinch, a hand near the neck, and a frightened person who did not fight back and said sorry. The State has not shown that {D} meant to hit an officer."),
        timeline: [(0, "{D} arrives at the county jail intake area and an officer begins a pat-down."), (0, "{D} yells, then swings and strikes {V} on the jaw, on camera."), (0, "Other officers restrain {D}.")],
        identified: "Intake camera.",
        aggravating: ["The victim was a law enforcement officer performing official duties"],
        impact: "I was just doing my job. I was patting down a detainee at intake, as I've done thousands of times, and a fist came toward my face. The camera shows the swing. I was lucky to get away with a bruise. Every officer in that room felt the same jolt.",
        genders: ["D": .male, "V": .male])

    static let wrenchAssaultThreat = SmallCases.make(
        key: "story.followup.wrenchAssaultThreat",
        category: .publicOrder,
        headlines: ["Mechanic Threatened Again After Wrench Case", "Defendant From Shop Assault Case Threatens Witness"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, a shop employee, on {DATE}.",
        ages: 24...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} called the shop and told {V}, an employee who had testified, 'I know where you park.' {V} saved the voicemail. {DL} says {D.he} meant no harm.",
