        role: "Shop employee",
        exam: [.direct("What is your job?", "\"I work at an auto repair shop. I turn wrenches and talk to customers at the counter, and I testified in {DL}'s earlier case.\""),
               .direct("What did the voicemail say?", "\"I know where you park. That was the whole message, and {DL} said it clearly and slowly.\""),
               .direct("When did you hear it?", "\"The same afternoon it was left. I played it, then saved it and played it again for a detective the next morning.\""),
               .direct("How did you feel?", "\"Afraid. I had just testified, and the message came in on the shop's own line, where anyone could have answered it.\""),
               .direct("What does the phone log show?", "\"A call from a number that belongs to {D}. It was a short call that went to voicemail.\""),
